+	resolved, err := git(ctx, p.Repository.Root, "rev-parse", "--verify", p.Repository.BaseCommit+"^{commit}")
+	if err != nil || resolved != p.Repository.BaseCommit { return errors.New("approved base is not a local commit") }
+	return nil
