+type Source struct { Files fs.FS; Directory string }
+
+type Expected struct { Version int; Name, Digest string }
+
+func Describe(sources ...Source) ([]Expected, error) {
+	var result []Expected
+	seen := map[int]bool{}
+	for _, source := range sources {
+		items, err := readAll(source.Files, source.Directory)
+		if err != nil { return nil, err }
+		for _, value := range items {
+			if seen[value.version] { return nil, fmt.Errorf("duplicate migration version %d", value.version) }
+			seen[value.version] = true
+			result = append(result, Expected{Version: value.version, Name: value.name, Digest: value.digest})
+		}
+	}
+	slices.SortFunc(result, func(a, b Expected) int { return a.Version - b.Version })
+	return result, nil
+}
+
