+	if err := checkDocker(ctx, value.Policy.Images.Execution); err != nil { failures["EXECUTION_IMAGE_MISMATCH"] = true }
+	if err := checkDocker(ctx, value.Policy.Images.Verification); err != nil { failures["VERIFICATION_IMAGE_MISMATCH"] = true }
