+		stat, ok := info.Sys().(*syscall.Stat_t)
+		if !ok || int(stat.Uid) != os.Geteuid() || info.Mode().Perm()&0o022 != 0 { return errors.New("unsafe permissions") }
+		for _, other := range paths[:index] {
